-- Seed profiles shaped for a cold-charged, heat-limited fluid-bed roaster
-- (docs/profiles.md). Generated by a declining-RoR model:
-- BT(t) = 30 + c·t + a·τ(1 − e^(−t/τ)), τ = 200 s, fitted to FC at 200 °C
-- and the drop temperature. Points every 30 s; fan 100 % through drying,
-- then easing to the late fan by first crack (fan assist trims below it).
-- Upserts: profile rows inserted or updated, points and events replaced.
-- The old generic profiles stay (sessions reference them), renamed.

UPDATE roast_profiles SET name = 'Generic light (legacy, drum-style)', description = description || ' Legacy example: starts at a 95 °C charge, and its fan curve (45-75 %) is too low for the fluid bed.' WHERE id = 'default-light';
UPDATE roast_profiles SET name = 'Generic medium (legacy, drum-style)', description = description || ' Legacy example: starts at a 95 °C charge, and its fan curve (45-75 %) is too low for the fluid bed.' WHERE id = 'default-medium';
UPDATE roast_profiles SET name = 'Generic dark (legacy, drum-style)', description = description || ' Legacy example: starts at a 95 °C charge, and its fan curve (45-75 %) is too low for the fluid bed.' WHERE id = 'default-dark';

DELETE FROM profile_points WHERE profile_id = 'fluidbed-light';
DELETE FROM profile_events WHERE profile_id = 'fluidbed-light';

DELETE FROM profile_points WHERE profile_id = 'fluidbed-medium';
DELETE FROM profile_events WHERE profile_id = 'fluidbed-medium';

DELETE FROM profile_points WHERE profile_id = 'fluidbed-espresso';
DELETE FROM profile_events WHERE profile_id = 'fluidbed-espresso';

